import sys

def main():
    data = sys.stdin.read().split()
    n = int(data[0])
    best = 0
    left = 0
    zeros = 0
    for right in range(n):
        if data[1 + right] == '0':
            zeros += 1
        while zeros > 1:
            if data[1 + left] == '0':
                zeros -= 1
            left += 1
        if right - left + 1 > best:
            best = right - left + 1
    print(best)

